CREATE TABLE IF NOT EXISTS compliance_requirements_archive_m820_c4d AS SELECT * FROM compliance_requirements WHERE false;
CREATE TABLE IF NOT EXISTS fields_archive_m820_c4d AS SELECT * FROM fields WHERE false;
CREATE TABLE IF NOT EXISTS m820_c4d_written (tbl text NOT NULL, id uuid NOT NULL, md5 text NOT NULL, PRIMARY KEY (tbl, id));

-- ── A · the TWO NEW phase drivers (C-9 pattern of 20261008100000: boolean, required, section B, order 0; inserted only when the symbol is
--       absent on the sheet; the ledger row 'fields_new' is written only for a row inserted by THIS run, so the rollback never deletes a row it
--       did not create). M820-17 phase_vergabeverfahren_erreicht first; M820-23 phase_auftrag_erteilt is shown only when it is Ja. ──
-- NEW DWA-M-820-1 M820-17 phase_vergabeverfahren_erreicht (boolean, required, section B, visible_when —, consumers M820-20, M820-21, M820-22, M820-23, M820-24)
WITH ins AS (
INSERT INTO fields (worksheet_template_id, section_id, symbol, label_de, label_en, data_type, unit, is_required, clause_reference, description, verification_status, verification_quote, source_anchor, widget, ui_config, visible_when, consumer_worksheets, order_index, active)
SELECT w.id, (SELECT ws.id FROM worksheet_sections ws WHERE ws.worksheet_template_id = w.id AND ws.code = 'B'), 'phase_vergabeverfahren_erreicht', $m$Vergabeverfahren begonnen (Bekanntmachung veröffentlicht bzw. Angebotsanfrage versandt)$m$, $m$Award procedure started (notice published or request for offer sent)$m$, 'boolean', NULL, true, $m$Anh. F; §8.10.3.5; §8.10.1; DWA-M 820-3 §2.1$m$,
       $m$Ja/Nein: Hat das Vergabeverfahren begonnen – Bekanntmachung veröffentlicht bzw. (Direktvergabe, Suchverfahren) die Anfrage an ein Ingenieurbüro versandt? Anhang F (S. 65): „Das Vergabeverfahren ist von Beginn an zu dokumentieren. Die Dokumentation muss die einzelnen Stufen des Verfahrens und die einzelnen Maßnahmen sowie die Begründung der einzelnen Entscheidungen festhalten (§ 8 VgV). Sie muss mit Verfahrensbeginn begonnen und zeitnah fortgeschrieben werden.“ § 8.10.3.5 (S. 41): „Folglich muss der Vertragsentwurf bereits mit der Bekanntmachung vorliegen, kann sodann verhandelt werden und ist vor der Wertung der endgültigen Angebote abschließend zu klären.“ § 8.10.1 (S. 38): „VgV-F-Verfahren müssen in zwei voneinander abgegrenzten Verfahrensschritten erfolgen, der Bewerbungsphase (siehe 8.10.2) und der Angebotsphase (siehe 8.10.3).“ Nein = Phase noch nicht erreicht: das Verhandlungsprotokoll (M820-20, 5 Angaben), die Vertragscheckliste (M820-21, 6), Versicherung und Haftung (M820-22, 4) sowie die Frage nach der Auftragserteilung und alles, was an ihr hängt (M820-23, M820-24), sind ausgeblendet; REQ-20, REQ-21, REQ-23 und REQ-23-2 gelten noch nicht. Ja: diese Angaben werden gefragt, REQ-21 gilt wie bisher; die Auftragsangaben folgen der Frage nach der Auftragserteilung (M820-23). Hat das Verfahren begonnen, die Antwort auf Ja setzen und das Blatt erneut zur Freigabe einreichen. Eine Konformitätserklärung deckt nur die Phasen ab, die hier als erreicht markiert sind. Unbeantwortet bleiben die Angaben sichtbar, und eine geltende Prüfung wartet (sperrt) und nennt diese Frage. Für Direktvergabe und Suchverfahren ist „Anfrage versandt“ eine Werkzeug-Lesart (das Merkblatt nennt dort keinen Verfahrensbeginn). Werkzeug-Frage; Phase im Sinne von DWA-M 820-3 § 2.1 (S. 8): „bestimmter Abschnitt des gesamten Projektablaufs, der einen eindeutigen Beginn und ein definiertes Ende aufweist“.
[EN] Yes/No: has the award procedure started – notice published or (direct award, search procedure) the request sent to an engineering office? Anhang F (p. 65): "the procurement procedure is to be documented from the beginning. The documentation must record the individual stages of the procedure and the individual measures as well as the reasons for the individual decisions (§ 8 VgV). It must be started with the beginning of the procedure and updated promptly." § 8.10.3.5 (p. 41): "consequently the contract draft must already be available with the publication notice, can then be negotiated and is to be settled conclusively before the final offers are scored." § 8.10.1 (p. 38): "VgV-F procedures must take place in two separate procedural steps, the application phase (see 8.10.2) and the offer phase (see 8.10.3)." No = phase not reached yet: the negotiation record (M820-20, 5 entries), the contract checklist (M820-21, 6), insurance and liability (M820-22, 4) and the question on the award with everything tied to it (M820-23, M820-24) are hidden; REQ-20, REQ-21, REQ-23 and REQ-23-2 do not apply yet. Yes: these entries are asked, REQ-21 applies as before; the award entries follow the award question (M820-23). When the procedure has started, set the answer to Yes and submit the sheet for approval again. A conformity declaration covers only the phases marked reached here. Unanswered, the entries stay visible, and an applicable check waits (blocks) and names this question. For a direct award and a search procedure "request sent" is a tool reading (the Merkblatt names no procedure start there). Tool question; phase in the sense of DWA-M 820-3 § 2.1 (p. 8): "a specific section of the entire project sequence that has a clear beginning and a defined end".$m$,
       'imported_unverified', $m$Anhang F (PDF S. 67 / gedruckt S. 65): „Das Vergabeverfahren ist von Beginn an zu dokumentieren. Die Dokumentation muss die einzelnen Stufen des Verfahrens und die einzelnen Maßnahmen sowie die Begründung der einzelnen Entscheidungen festhalten (§ 8 VgV). Sie muss mit Verfahrensbeginn begonnen und zeitnah fortgeschrieben werden.“ § 8.10.3.5 (PDF S. 43 / gedruckt S. 41): „Folglich muss der Vertragsentwurf bereits mit der Bekanntmachung vorliegen, kann sodann verhandelt werden und ist vor der Wertung der endgültigen Angebote abschließend zu klären.“ § 8.10.1 (PDF S. 40 / gedruckt S. 38): „VgV-F-Verfahren müssen in zwei voneinander abgegrenzten Verfahrensschritten erfolgen, der Bewerbungsphase (siehe 8.10.2) und der Angebotsphase (siehe 8.10.3).“ DWA-M 820-3 § 2.1 (PDF S. 10 / gedruckt S. 8): „bestimmter Abschnitt des gesamten Projektablaufs, der einen eindeutigen Beginn und ein definiertes Ende aufweist“$m$, $m$DWA-M 820-1 Anh. F Z.1705 (PDF S. 67) + DWA-M 820-1 §8.10.3.5 Z.1046 (PDF S. 43) + DWA-M 820-1 §8.10.1 Z.947 (PDF S. 40) + DWA-M 820-3 §2.1 Z.219 (PDF S. 10)$m$, NULL, NULL, NULL, ARRAY['M820-20', 'M820-21', 'M820-22', 'M820-23', 'M820-24']::text[], 0, true
  FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id
 WHERE s.code = 'DWA-M-820-1' AND w.code = 'M820-17'
   AND NOT EXISTS (SELECT 1 FROM fields f2 WHERE f2.worksheet_template_id = w.id AND f2.symbol = 'phase_vergabeverfahren_erreicht')
RETURNING *)
INSERT INTO m820_c4d_written (tbl, id, md5) SELECT 'fields_new', ins.id, md5(row_to_json(ins)::text) FROM ins;
-- NEW DWA-M-820-1 M820-23 phase_auftrag_erteilt (boolean, required, section B, visible_when phase_vergabeverfahren_erreicht == true, consumers M820-20, M820-24)
WITH ins AS (
INSERT INTO fields (worksheet_template_id, section_id, symbol, label_de, label_en, data_type, unit, is_required, clause_reference, description, verification_status, verification_quote, source_anchor, widget, ui_config, visible_when, consumer_worksheets, order_index, active)
SELECT w.id, (SELECT ws.id FROM worksheet_sections ws WHERE ws.worksheet_template_id = w.id AND ws.code = 'B'), 'phase_auftrag_erteilt', $m$Auftrag an das Ingenieurbüro erteilt (Vergabeverfahren abgeschlossen)$m$, $m$Contract awarded to the engineering office (procurement procedure completed)$m$, 'boolean', NULL, true, $m$§8.10.3.1, §8.10.3.6; DWA-M 820-3 §2.1$m$,
       $m$Ja/Nein: Ist der Auftrag an das Ingenieurbüro erteilt, also der Ingenieurvertrag geschlossen und das Vergabeverfahren damit abgeschlossen? Nur gefragt, wenn das Vergabeverfahren begonnen hat (phase_vergabeverfahren_erreicht = Ja, M820-17). Gegenstand dieses Teils ist die Vergabe von Ingenieurleistungen – § 1 (S. 10): „Der Anwendungsbereich des Merkblatts reicht – mit dem Ziel der Qualitätssicherung – von der Konzepterstellung für ein Gesamtsystem über die Vergabe von Ingenieurleistungen (vorliegender Teil 1) bis zur Durchführung von Projekten, Inbetriebnahme, Übergabe und Erfolgskontrolle von Anlagen (Teil 2, in Vorbereitung).“ § 8.10.3.1 (S. 40): „Erst mit Auftragserteilung ist das Vergabeverfahren abgeschlossen.“ § 8.10.3.6 (S. 42): „Mit Auftragserteilung endet das Vergabeverfahren.“ Nein = Phase noch nicht abgeschlossen: Auftragsdatum und Auftragnehmer (dieses Blatt, 2 Angaben) und der Dokumentationsabschluss (M820-24, 5; dort außerdem nur bei an das Vergaberecht gebundenem Auftraggeber oder freiwilliger Anwendung) sind ausgeblendet; REQ-20 (Anzahl der Verhandlungsrunden, M820-20), REQ-23 und REQ-23-2 gelten noch nicht. Ja: die Angaben werden gefragt und die Prüfungen gelten wie bisher. Ist der Auftrag erteilt, die Antwort auf Ja setzen und die Blätter erneut zur Freigabe einreichen. Eine Konformitätserklärung deckt nur die Phasen ab, die hier als abgeschlossen markiert sind. Unbeantwortet bleiben die Angaben sichtbar, und eine geltende Prüfung wartet (sperrt) und nennt diese Frage. Die Informationsschreiben und die Wartefrist (dieses Blatt, § 134 GWB) liegen vor der Auftragserteilung und bleiben unabhängig von dieser Frage sichtbar – § 8.10.3.6 (S. 42): „Vor Auftragserteilung hat der Auftraggeber die Bewerber und Bieter, die keinen Auftrag erhalten sollen, über die Gründe ihrer Nichtberücksichtigung zu informieren.“ Gleiches Ereignis wie die Frage phase_auftrag_erteilt auf 820-2-09 (DWA-M 820-2, Vertrag mit dem Planer / Ingenieurbüro): beide Antworten gleich halten. Werkzeug-Frage; Phase im Sinne von DWA-M 820-3 § 2.1 (S. 8): „bestimmter Abschnitt des gesamten Projektablaufs, der einen eindeutigen Beginn und ein definiertes Ende aufweist“.
[EN] Yes/No: is the contract awarded to the engineering office, i.e. the engineering contract concluded and the procurement procedure thus completed? Asked only once the award procedure has started (phase_vergabeverfahren_erreicht = yes, M820-17). This part concerns the award of engineering services – § 1 (p. 10): "the scope of the Merkblatt extends – with the aim of quality assurance – from drawing up a concept for an overall system via the award of engineering services (present Part 1) to the execution of projects, commissioning, handover and performance review of facilities (Part 2, in preparation)." § 8.10.3.1 (p. 40): "only with the award of the contract is the procurement procedure completed." § 8.10.3.6 (p. 42): "the procurement procedure ends with the award of the contract." No = phase not completed yet: award date and contractor (this sheet, 2 entries) and the documentation close-out (M820-24, 5; there in addition only for a client bound by procurement law or applying it voluntarily) are hidden; REQ-20 (number of negotiation rounds, M820-20), REQ-23 and REQ-23-2 do not apply yet. Yes: the entries are asked and the checks apply as before. When the contract is awarded, set the answer to Yes and submit the sheets for approval again. A conformity declaration covers only the phases marked completed here. Unanswered, the entries stay visible, and an applicable check waits (blocks) and names this question. The information letters and the standstill period (this sheet, § 134 GWB) come before the award and stay visible regardless of this question – § 8.10.3.6 (p. 42): "before the award, the client has to inform the applicants and bidders who are not to receive the contract of the reasons why they were not considered." Same event as the question phase_auftrag_erteilt on 820-2-09 (DWA-M 820-2, contract with the planner / engineering office): keep both answers the same. Tool question; phase in the sense of DWA-M 820-3 § 2.1 (p. 8): "a specific section of the entire project sequence that has a clear beginning and a defined end".$m$,
       'imported_unverified', $m$§ 8.10.3.1 (PDF S. 42 / gedruckt S. 40): „Erst mit Auftragserteilung ist das Vergabeverfahren abgeschlossen.“ § 8.10.3.6 (PDF S. 44 / gedruckt S. 42): „Mit Auftragserteilung endet das Vergabeverfahren.“ § 1 (PDF S. 12 / gedruckt S. 10): „Der Anwendungsbereich des Merkblatts reicht – mit dem Ziel der Qualitätssicherung – von der Konzepterstellung für ein Gesamtsystem über die Vergabe von Ingenieurleistungen (vorliegender Teil 1) bis zur Durchführung von Projekten, Inbetriebnahme, Übergabe und Erfolgskontrolle von Anlagen (Teil 2, in Vorbereitung).“ DWA-M 820-3 § 2.1 (PDF S. 10 / gedruckt S. 8): „bestimmter Abschnitt des gesamten Projektablaufs, der einen eindeutigen Beginn und ein definiertes Ende aufweist“$m$, $m$DWA-M 820-1 §8.10.3.1 Z.1001 (PDF S. 42) + DWA-M 820-1 §8.10.3.6 Z.1066 (PDF S. 44) + DWA-M 820-1 §1 Z.281 (PDF S. 12) + DWA-M 820-3 §2.1 Z.219 (PDF S. 10)$m$, NULL, NULL, $m$phase_vergabeverfahren_erreicht == true$m$, ARRAY['M820-20', 'M820-24']::text[], 0, true
  FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id
 WHERE s.code = 'DWA-M-820-1' AND w.code = 'M820-23'
   AND NOT EXISTS (SELECT 1 FROM fields f2 WHERE f2.worksheet_template_id = w.id AND f2.symbol = 'phase_auftrag_erteilt')
RETURNING *)
INSERT INTO m820_c4d_written (tbl, id, md5) SELECT 'fields_new', ins.id, md5(row_to_json(ins)::text) FROM ins;

